<script setup>
import { computed,onMounted,reactive,ref,watch } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import { HostSurface } from '../../platform/host-adapter.mjs'; import { createAwardsApi } from './domain/awards-api.mjs'; import { awardDetailViewModel,awardsListViewModel } from './domain/award-view.mjs'; import AwardsListDesktop from './desktop/AwardsListDesktop.vue'; import AwardDetailDesktop from './desktop/AwardDetailDesktop.vue'; import AwardFormDesktop from './desktop/AwardFormDesktop.vue'; import AwardsListMobile from './mobile/AwardsListMobile.vue'; import AwardDetailMobile from './mobile/AwardDetailMobile.vue'; import AwardFormMobile from './mobile/AwardFormMobile.vue';
const props=defineProps({awardId:{type:Number,default:null},surface:String,adapter:Object,hostUnavailable:Boolean});const emit=defineEmits(['back']);const api=createAwardsApi();const isNative=computed(()=>props.surface===HostSurface.NATIVE);const safeArea=ref(props.adapter?.getSafeArea?.()||{});const state=reactive({phase:'loading',rows:[],total:0,page:1,pageSize:20,search:'',detail:null,record:null,permissions:null,mode:'read',saving:false,saveError:'',error:null});const canCreate=computed(()=>state.permissions?.modules?.awards?.includes('create')===true);const canEdit=computed(()=>state.permissions?.modules?.awards?.includes('edit')===true);const safeAreaStyle=computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap(s=>Number.isFinite(Number(safeArea.value?.[s]))?[[`--mds-mobile-safe-${s}`,`${Number(safeArea.value[s])}px`]]:[])));
async function load({page=state.page,search=state.search}={}){if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng.'};return;}state.phase='loading';try{const user=api.getCurrentUser();if(props.awardId){const[p,u]=await Promise.all([api.get(props.awardId),user]);Object.assign(state,{detail:awardDetailViewModel(p),record:p.record,permissions:u.permissions||null,mode:'detail',phase:'ready'});return;}const[p,u]=await Promise.all([api.getList({page,pageSize:20,search}),user]);Object.assign(state,{...awardsListViewModel(p),permissions:u.permissions||null,mode:'read',phase:'ready'});}catch(error){state.phase='error';state.error=error;}}
function open(id){location.hash=`awards/${Number(id)}`;}function list(){location.hash='awards';}function create(){if(canCreate.value){state.mode='create';state.saveError='';}}function edit(){if(canEdit.value){state.mode='edit';state.saveError='';}}async function save(input){state.saving=true;try{const row=await api.save(input,props.awardId);if(props.awardId)await load();else location.hash=`awards/${row.id}`;}catch(error){state.saveError=error.message;}finally{state.saving=false;}}function back(){if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'awards'});emit('back');}watch(()=>props.awardId,()=>load());onMounted(load);
</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center':'grid min-h-[360px] place-items-center'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app':'p-4'"><MMobileTopBar v-if="isNative" title="Giải thưởng" @back="back"/><MEmptyState title="Không thể mở giải thưởng" :description="state.error.message"/></section><AwardFormMobile v-else-if="isNative&&['create','edit'].includes(state.mode)" :record="state.record" :editing="state.mode==='edit'" :saving="state.saving" :error="state.saveError" :safe-area-style="safeAreaStyle" @cancel="state.mode=props.awardId?'detail':'read'" @save="save"/><AwardDetailMobile v-else-if="isNative&&state.mode==='detail'" :detail="state.detail" :can-edit="canEdit" :safe-area-style="safeAreaStyle" @back="list" @edit="edit"/><AwardsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :can-create="canCreate" :safe-area-style="safeAreaStyle" @back="back" @create="create" @open="open" @page="load({page:$event})" @search="load({page:1,search:$event})"/><AwardFormDesktop v-else-if="['create','edit'].includes(state.mode)" :record="state.record" :editing="state.mode==='edit'" :saving="state.saving" :error="state.saveError" @cancel="state.mode=props.awardId?'detail':'read'" @save="save"/><AwardDetailDesktop v-else-if="state.mode==='detail'" :detail="state.detail" :can-edit="canEdit" @back="list" @edit="edit"/><AwardsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :loading="state.phase==='loading'" :can-create="canCreate" @create="create" @open="open" @page="load({page:$event})" @search="load({page:1,search:$event})"/></template>
